235	/**
236	 * Loads public/app.js (or `source`) into a fresh fake page. The script's only
237	 * globals are `document` and `fetch` (plus the JS built-ins).
238	 */
239	export function loadApp({ source = readFileSync(APP_PATH, 'utf8'), setup } = {}) {
240	  const page = new FakePage();
241	  if (setup) setup(page);
242	  const context = vm.createContext({ document: page.makeDocument(), fetch: page.makeFetch() });
243	  new vm.Script(source, { filename: 'app.js' }).runInContext(context);
244	  return page;
245	}
